// Normalize input to a valid 4-bit AArch64 condition code [0..15].
// This avoids AArch64CC_Invalid (enum value after 0xF) which would assert in this API.
AArch64CC_CondCode safe_code = (AArch64CC_CondCode)((int)(*code) & 0xF);

// Call the target function. Requirement: Code must be recognized; ensured by normalization above.
const char *name = AArch64CC_getCondCodeName(safe_code);

// Property: a valid condition code must have a non-null, non-empty mnemonic.
FUZZ_ASSERT(name != nullptr, "AArch64CC_getCondCodeName returned null");
FUZZ_ASSERT(name[0] != '\0', "AArch64CC_getCondCodeName returned empty string");

// Validation: Inputs are value-only, no ownership changes. No outputs to return.
// This stub ensures the code is within the valid set and asserts mnemonic soundness.

// Prefer a canonical 4-bit code to exercise meaningful inversion pairs.
AArch64CC_CondCode safe_code = (AArch64CC_CondCode)((int)(*code) & 0xF);

// Call the target and verify an involution: invert twice yields the original code.
AArch64CC_CondCode inv = AArch64CC_getInvertedCondCode(safe_code);
AArch64CC_CondCode inv2 = AArch64CC_getInvertedCondCode(inv);
FUZZ_ASSERT((int)inv2 == (int)safe_code, "Double inversion did not return original code");

// Validation: Pure value semantics; no persistent objects. Ensures broad coverage across code space.

// Constrain to valid 4-bit condition code to satisfy function precondition (avoids assert paths).
AArch64CC_CondCode safe_code = (AArch64CC_CondCode)((int)(*code) & 0xF);

// Invoke target; it returns NZCV bits encoded as N=8,Z=4,C=2,V=1.
unsigned nzcv = AArch64CC_getNZCVToSatisfyCondCode(safe_code);

// Validate encoding: Only the low 4 bits may be set.
FUZZ_ASSERT((nzcv & ~0xFu) == 0u, "NZCV contains bits outside N/Z/C/V mask");

// Optional sanity: at least one assignment should be representable for any valid code (nzcv within 0..15 already ensures that).

// Validation: Input normalized; result sanity-checked; no ownership involved.

// Normalize to canonical 4-bit code. Function accepts any code, but this keeps behavior meaningful.
AArch64CC_CondCode safe_code = (AArch64CC_CondCode)((int)(*code) & 0xF);

// Invoke target function.
bool r = AArch64CC_isReflexive(safe_code);

// Basic consistency property with inversion: a code cannot be both strictly reflexive and strictly irreflexive.
bool irr = AArch64CC_isIrreflexive(safe_code);
FUZZ_ASSERT(!(r && irr), "Condition code reported both reflexive and irreflexive");

// Validation: Pure query; no side effects. Ensures mutual-exclusion property against irreflexive.

// Normalize to canonical 4-bit code for meaningful semantics.
AArch64CC_CondCode safe_code = (AArch64CC_CondCode)((int)(*code) & 0xF);

// Invoke target function.
bool irr = AArch64CC_isIrreflexive(safe_code);

// Cross-check with reflexive: cannot be both.
bool r = AArch64CC_isReflexive(safe_code);
FUZZ_ASSERT(!(irr && r), "Condition code reported both irreflexive and reflexive");

// Validation: Value-only; asserts logical consistency with reflexive predicate.

// Generate a valid ARM condition code (excluding AL/UNDEF/Invalid) and verify properties
ARMCC_CondCodes valid_list[14] = {
    ARMCC_EQ, ARMCC_NE, ARMCC_HS, ARMCC_LO, ARMCC_MI, ARMCC_PL,
    ARMCC_VS, ARMCC_VC, ARMCC_HI, ARMCC_LS, ARMCC_GE, ARMCC_LT,
    ARMCC_GT, ARMCC_LE
};
unsigned pick = *FUZZ_PARAM(unsigned int) % 14;
ARMCC_CondCodes in = valid_list[pick];
ARMCC_CondCodes out = ARMCC_getOppositeCondition(in);
// Property: opposite(opposite(x)) == x for all supported conditions
FUZZ_ASSERT(ARMCC_getOppositeCondition(out) == in, "Opposite is involutive");
// Also ensure output is within the valid set above (not AL/UNDEF/Invalid)
bool ok = false; for (int i = 0; i < 14; ++i) if (valid_list[i] == out) { ok = true; break; }
FUZZ_ASSERT(ok, "Opposite must be a valid condition");

// Exercise both supported and unsupported swap cases
ARMCC_CondCodes any_list[17] = {
    ARMCC_EQ, ARMCC_NE, ARMCC_HS, ARMCC_LO, ARMCC_MI, ARMCC_PL,
    ARMCC_VS, ARMCC_VC, ARMCC_HI, ARMCC_LS, ARMCC_GE, ARMCC_LT,
    ARMCC_GT, ARMCC_LE, ARMCC_AL, ARMCC_UNDEF, ARMCC_Invalid
