import random
import string

# Data type: short lowercase token for ARM condition codes
# Valid canonical tokens per stub
VALID_TOKENS = [
    "eq","ne","hs","cs","lo","cc","mi","pl","vs","vc",
    "hi","ls","ge","lt","gt","le","al"
]

# Some interesting invalid-but-structured tokens to exercise negative paths
INTERESTING_INVALID = [
    "zz",  # explicitly used by the stub as an invalid mix
    "aa", "bb", "xx", "yy",
    "eqx",  # near-valid with extra char
    "nn",   # not a valid mnemonic
    "cond", # max-length style (trimmed by harness if longer than 4)
]

# Distribution helper: mix valid, near-valid, and random
def _choose_token(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.5:
        # valid token
        return rng.choice(VALID_TOKENS)
    elif choice < 0.8:
        # interesting invalid
        return rng.choice(INTERESTING_INVALID)
    else:
        # random short lowercase (length 1..4)
        length = rng.randint(1, 4)
        return ''.join(rng.choice(string.ascii_lowercase) for _ in range(length))

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    token = _choose_token(rng)
    # Ensure lowercase and within 4 chars (harness trims, but keep valid form)
    token = token.lower()[:4]
    return token.encode('ascii')
